I left out both operations requests. The node's world is confined to `Notifier<'digest'>`. It has no filesystem and no HTTP capability, and the target has no WASI, so a log file write or a metadata fetch has no import to go through. Adding either would mean widening the node's authority, which should be a graph-level decision. The output is unchanged either way.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{digest, published-digest};

    import aap:caps/notifier@0.1.0;

    export run: func(composed: digest) -> published-digest;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::notifier;

struct Node;

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let mut msg = String::new();
        msg.push_str("Digest ");
        msg.push_str(&composed.date);
        msg.push('\n');
        msg.push_str(&composed.overview);
        for e in composed.entries.iter().filter(|e| e.kept) {
            msg.push('\n');
            msg.push_str("- ");
            msg.push_str(&e.title);
            msg.push_str(" (");
            msg.push_str(&e.link);
            msg.push_str("): ");
            msg.push_str(&e.summary);
        }

        let published = notifier::notify(&msg);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
